custom_fields.clock:
[[[
  const now = new Date();
  const hours = String(now.getHours()).padStart(2, '0');
  const minutes = String(now.getMinutes()).padStart(2, '0');
  return `<div class="home-clock">${hours}:${minutes}</div>`;
]]]

custom_fields.date:
[[[
  const now = new Date();
  const weekdayRaw = now.toLocaleDateString('da-DK', { weekday: 'long' });
  const monthRaw = now.toLocaleDateString('da-DK', { month: 'long' });
  const weekday = weekdayRaw.charAt(0).toUpperCase() + weekdayRaw.slice(1);
  const day = now.getDate();
  return `<div class="home-date">${weekday} d. ${day}. ${monthRaw}</div>`;
]]]

custom_fields.weather_line:
[[[
  const tempSensor = states['sensor.udendors_temperatur'];
  const weather = states['weather.forecast_home'];

  let temp = null;

  if (tempSensor && tempSensor.state !== 'unknown' && tempSensor.state !== 'unavailable' && !isNaN(Number(tempSensor.state))) {
    temp = Number(tempSensor.state).toLocaleString('da-DK', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
  } else if (weather && weather.attributes.temperature !== undefined && !isNaN(Number(weather.attributes.temperature))) {
    temp = Number(weather.attributes.temperature).toLocaleString('da-DK', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
  }

  const iconMap = {
    'clear-night': 'mdi:weather-night',
    cloudy: 'mdi:weather-cloudy',
    exceptional: 'mdi:weather-tornado',
    fog: 'mdi:weather-fog',
    hail: 'mdi:weather-hail',
    lightning: 'mdi:weather-lightning',
    'lightning-rainy': 'mdi:weather-lightning-rainy',
    partlycloudy: 'mdi:weather-partly-cloudy',
    pouring: 'mdi:weather-pouring',
    rainy: 'mdi:weather-rainy',
    snowy: 'mdi:weather-snowy',
    'snowy-rainy': 'mdi:weather-snowy-rainy',
    sunny: 'mdi:weather-sunny',
    windy: 'mdi:weather-windy',
    'windy-variant': 'mdi:weather-windy-variant'
  };

  const weatherMap = {
    'clear-night': 'klart',
    cloudy: 'skyet',
    exceptional: 'ekstremt',
    fog: 'tåge',
    hail: 'hagl',
    lightning: 'lyn',
    'lightning-rainy': 'tordenregn',
    partlycloudy: 'delvist skyet',
    pouring: 'kraftig regn',
    rainy: 'regn',
    snowy: 'sne',
    'snowy-rainy': 'slud',
    sunny: 'sol',
    windy: 'blæsende',
    'windy-variant': 'blæsende'
  };

  const conditionRaw = weather?.state || '';
  const condition = weatherMap[conditionRaw] || conditionRaw || '';
  const icon = iconMap[conditionRaw] || 'mdi:weather-cloudy';
  const tempText = temp !== null ? temp + '°' : '--°';

  return '<span style="display:inline-flex;align-items:center;vertical-align:middle;"><span style="font-size:30px;font-weight:800;color:#F4F6F2;">' + tempText + '</span><span style="font-size:30px;font-weight:600;color:rgba(244,246,242,0.42);margin:0 6px;">|</span><span style="font-size:30px;font-weight:800;color:#F4F6F2;">' + condition + '</span><ha-icon icon="' + icon + '" style="width:33px;height:33px;color:#F4F6F2;margin-left:10px;"></ha-icon></span>';
]]]

