custom_fields.family_presence:
[[[
  const people = [
    {
      person: 'person.brian_dalsgaard_hansen',
      tracker: 'device_tracker.iphone_5'
    },
    {
      person: 'person.iben_dalsgaard_hansen',
      tracker: 'device_tracker.iphone_9'
    },
    {
      person: 'person.caroline_ferslev_dalsgaard_hansen',
      tracker: 'device_tracker.iphone'
    }
  ];

  return `
    <div class="family-row">
      ${people.map(p => {
        const person = states[p.person];
        const tracker = states[p.tracker];
