custom_fields.header:
[[[
  const groups = [
    'light.stue_lights',
    'light.kontor_lights',
    'light.kokken_lights',
    'light.nordtronic_a_s_rotdimz_98424072',
    'light.caroline_lights',
    'light.sovevaerelse'
  ];

  let total = 0;
  let on = 0;

  groups.forEach(id => {
    const g = states[id];
    const members = g?.attributes?.entity_id;

    if (Array.isArray(members) && members.length > 0) {
      members.forEach(mid => {
        const m = states[mid];
        if (m) {
          total++;
          if (m.state === 'on') on++;
        }
      });
    } else if (g) {
      total++;
      if (g.state === 'on') on++;
    }
  });

  return `
    <div class="page-title">Lys</div>
    <div class="page-subtitle">${on} / ${total} lys tændt</div>
  `;
]]]

custom_fields.idle_return:
[[[
  if (!window.minipanelIdleReturnInstalled) {
    window.minipanelIdleReturnInstalled = true;

    const timeout = 60000;
    const returnPath = '/dashboard-minipanel/home';

    let timer;

    const resetTimer = () => {
      clearTimeout(timer);

      timer = setTimeout(() => {
        const path = window.location.pathname;
        const search = window.location.search || '';

        if (
          path.startsWith('/dashboard-minipanel') &&
          !search.includes('disable_km') &&
          path !== '/dashboard-minipanel/home'
        ) {
          history.pushState(null, '', returnPath);
          window.dispatchEvent(new Event('location-changed'));
        }
      }, timeout);
    };

    ['click', 'touchstart', 'mousemove', 'keydown'].forEach(eventName => {
      document.addEventListener(eventName, resetTimer, true);
    });

    resetTimer();
  }

  return '';
]]]

