  const salt = states['binary_sensor.opvaskemaskine_salt_refill'];

  const doorOpen = door?.state === 'on';

  let running = false;
  let remainingText = 'Ingen aktiv tid';

  if (
    remaining &&
    remaining.state !== 'unknown' &&
    remaining.state !== 'unavailable' &&
    !isNaN(Number(remaining.state)) &&
    Number(remaining.state) > 0
  ) {
    running = true;
    const minutes = Math.round(Number(remaining.state));
    remainingText = `Kører · ${minutes} ${minutes === 1 ? 'minut' : 'minutter'} tilbage`;
  }

  const refill = (e) => {
    if (!e || e.state === 'unknown' || e.state === 'unavailable') return 'Ukendt';
    return e.state === 'on' ? 'Mangler' : 'OK';
  };

  const problem =
    doorOpen ||
    autoDose?.state === 'on' ||
    rinse?.state === 'on' ||
    salt?.state === 'on';

  const iconClass = problem ? 'warn' : running ? 'active' : '';

  return `
